#!/usr/bin/env bash
# release.sh VERSION: a release of k2lean (PKG-8), run from a clean checkout of k-rust on main.
#
# A release is one commit of k-rust: the generator (crate k2lean, version VERSION) and the Lake package
# `k2lean` (k2lean/lean, KPrelude.version = VERSION) at that commit, for one Lean toolchain (the
# package's lean-toolchain, in the tag's name). A library generated by that release's binary requires
# the package by git at that commit (`require k2lean from git … @ COMMIT / "k2lean/lean"`), and its root
# module checks the release (`#k2l_check_prelude "VERSION"`).
#
# The script makes the release commit and its tag `k2lean-vVERSION-<toolchain>`, then a commit that sets
# KPrelude.version back to `dev`; it prints the command that builds the release binary (with the commit
# embedded: K2LEAN_PACKAGE_GIT) and the push. It pushes nothing.
set -euo pipefail

version=${1:?usage: release.sh VERSION (for example 0.2.0)}
url=${K2LEAN_RELEASE_URL:-https://github.com/midnightntwrk/k-rust}
root=$(git rev-parse --show-toplevel)
cd "$root"

[[ $version =~ ^[0-9]+\.[0-9]+\.[0-9]+$ ]] || { echo "release.sh: VERSION is MAJOR.MINOR.PATCH" >&2; exit 2; }
[ "$(git branch --show-current)" = main ] || { echo "release.sh: not on main" >&2; exit 2; }
[ -z "$(git status --porcelain)" ] || { echo "release.sh: the checkout is not clean" >&2; exit 2; }

toolchain=$(sed 's|.*:v\{0,1\}||' k2lean/lean/lean-toolchain)   # 4.34.0
tag="k2lean-v$version-lean$toolchain"
git rev-parse -q --verify "refs/tags/$tag" > /dev/null && { echo "release.sh: tag $tag exists" >&2; exit 2; }

version_lean=k2lean/lean/prelude/KPrelude/Version.lean
cargo_toml=k2lean/crates/k2lean/Cargo.toml
set_version() { # VALUE: KPrelude.version
  sed -i "s|^def version : String := \".*\"|def version : String := \"$1\"|" "$version_lean"
  grep -q "^def version : String := \"$1\"" "$version_lean"
}

# the release commit: the generator's version and the package's are the same
sed -i "0,/^version = \".*\"/s//version = \"$version\"/" "$cargo_toml"
set_version "$version"
cargo metadata --offline --format-version 1 > /dev/null                   # Cargo.lock follows the crate version
git add "$cargo_toml" "$version_lean" Cargo.lock
git commit -q -m "k2lean $version (Lean $toolchain)"
commit=$(git rev-parse HEAD)
git tag -a "$tag" -m "k2lean $version, Lean $toolchain" "$commit"

# development goes on with the package at `dev`, which any generated library accepts
set_version dev
git add "$version_lean"
git commit -q -m "k2lean: KPrelude.version back to dev after $version"

cat <<EOF
release $version: commit $commit, tag $tag

build the release binary (libraries it generates require the package at this commit):
  git checkout $tag && K2LEAN_PACKAGE_GIT=$url@$commit cargo build --release -p k2lean --locked

publish (nothing is pushed by this script):
  git push origin main $tag
EOF
